package com.yeyamo_mobile.api.referral_service.infrastructure.web;import org.springframework.context.annotation.*;import io.swagger.v3.oas.models.*;import io.swagger.v3.oas.models.info.Info;import io.swagger.v3.oas.models.security.*;
@Configuration public class OpenApiConfig{@Bean OpenAPI referralOpenApi(){return new OpenAPI().info(new Info().title("YeYamo Referral API").version("v1").description("Referral codes, attribution, anti-fraud and rewards")).components(new Components().addSecuritySchemes("bearerAuth",new SecurityScheme().type(SecurityScheme.Type.HTTP).scheme("bearer").bearerFormat("JWT"))).addSecurityItem(new SecurityRequirement().addList("bearerAuth"));}}
